    ('Como calcular média, moda e mediana (questão de concurso público)', 'zx9n2hzsZLo', NULL, 'Estatística', 'Medidas de tendência central'),
    ('Distribuição binomial - exercícios para concursos', 'MsFZj5Dq7kY', NULL, 'Estatística', 'Probabilidade'),
    ('Dica para calcular probabilidade da distribuição normal padrão', 'FuqLDPv0Woo', NULL, 'Estatística', 'Probabilidade'),
    ('Distribuição binomial e normal - estatística (Sefa PA)', 'kJZ9vcik8Jk', NULL, 'Estatística', 'Probabilidade'),
    ('Probabilidade Aula 18 - distribuições de Bernoulli e binomial', '5EyJARJ6bo4', NULL, 'Estatística', 'Probabilidade')
) AS v(titulo, youtube_id, canal, disciplina, assunto)
JOIN disciplina d ON d.nome = v.disciplina
JOIN LATERAL (SELECT MIN(id) AS id FROM assunto x WHERE x.disciplina_id = d.id AND x.nome = v.assunto) a ON a.id IS NOT NULL
WHERE NOT EXISTS (SELECT 1 FROM videoaula x WHERE x.youtube_id = v.youtube_id);
